'confirm-submit':()=>{if(!can(1))return deny();if(Object.keys(validateAll()).length||!state.checks['613:4956'])return submit();const id=state.editing||'M'+Date.now().toString().slice(-9),v=state.values,base=rows.find(r=>r['公司 MID']===id);const entry={...(base||rows[0]),'客戶中文名稱':v.merchantName,'客戶英文名稱':v.merchantEnglishName,'公司 MID':id,BR:v.registerCertNo,'BR 有效期':v.registerCertPeriod,'DBA no.':v.dbaNo,'客戶聯繫人':v.contactName,'聯絡人電話':v.contactPhone,'聯絡人電郵':v.contactEmail,'MCC 行業代碼':v.mcc,'行業類型':v.merchantProfile,'銀行名稱':v.cardBankName,'銀行代碼':v.cardBankCode.slice(0,3),'分行代碼':v.cardBranchCode,bank:v.cardNo,'銀行帳號':mask(v.cardNo),status:'Pending',owner:BO.user.id,createdDay:23,application:structuredClone(draftSnapshot()),vip:false};if(BO.user.role===roles[2]){entry['主代理商']=BO.user.name;entry['主代理商代碼']=BO.user.agencyCode;}if(BO.user.role===roles[3]){entry['次代理商']=BO.user.name;entry['次代理商代碼']=BO.user.agencyCode;}if(base)Object.assign(base,entry);else rows.unshift(entry);state.drafts=state.drafts.filter(d=>d.id!==state.draftId);state.savedAt=new Date().toLocaleString();state.draftId=null;persistMerchantChange('提交商戶申請 · '+v.merchantName);modal('申請提交成功',`<div class="notice">申請已建立，等待審核。</div><p>申請編號：<strong>${id}</strong></p><p>${esc(v.merchantName)}</p>`,btn('查看商戶','open-merchants','primary'));},
